// CRTP for Static Dispatch (Zero Overhead Policy)
template <typename Derived>
struct BasePolicy {
    // Memory: No VTABLE pointer (vptr) added
    int data = 1;

    void interface() {
        // Static Dispatch: Function target known at compile time
        // Allows aggressive inlining and optimization
        static_cast<Derived*>(this)->execute();
    }
};

struct FastImplementation : BasePolicy<FastImplementation> {
    // Compile-time specialization
    void execute() { /* highly optimized logic */ }
};

// Usage: FastImplementation f; f.interface();
// Compiler generates specialized code block directly.
